    and .release_review_collection_count == ([.artifacts[] | select(.role == "release_review_collection")] | length)
    and .release_review_gate_count == ([.artifacts[] | select(.role == "release_review_gate")] | length)
    and .release_review_operator_handoff_count == ([.artifacts[] | select(.role == "release_review_operator_handoff")] | length)
    and .release_review_checkpoint_count == ([.artifacts[] | select(.role == "release_review_checkpoint")] | length)
    and .release_review_checklist_count == ([.artifacts[] | select(.role == "release_review_checklist")] | length)
    and .release_review_log_count == ([.artifacts[] | select(.role == "release_review_log")] | length)
    and .reviewed_runtime_artifact_count == 16
    and .reviewed_packet_fixture_count == 9
    and $review.artifact_count == .artifact_count
    and $review.release_review_input_count == .release_review_input_count
    and $review.release_review_visual_evidence_count == .release_review_visual_evidence_count
    and $review.release_review_recording_count == .release_review_recording_count
    and $review.release_review_collection_count == .release_review_collection_count
    and $review.release_review_gate_count == .release_review_gate_count
