  and group_sum("tracked_modified_count") == .tracked_modified_count
  and group_sum("untracked_count") == .untracked_path_count
  and .release_review_artifact_count == .release_review_snapshot.artifact_count
  and .release_review_failure_count == .release_review_snapshot.failure_count
  and .repository_ahead_count == .repository.ahead_count
  and .repository_behind_count == .repository.behind_count
  and (.repository.branch | type == "string" and length > 0)
  and (.repository.head_sha | type == "string" and length >= 7)
  and .release_review_snapshot.green == (.release_review_snapshot.failure_count == 0)
  and .release_review_snapshot.ready_for_release_review == true
